from collections import defaultdict

def is_good_cutting_point(edges, node):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * len(edges) + [True]
    parent = [None] * len(edges)

    def dfs(u, parent):
        visited[u] = True
        if parent:
            parent[u] = parent[parent[u]]
        children = []
        for v in graph[u]:
            if not visited[v]:
                children.append((v, dfs(v, u)))
        if parent and children:
            return None
        children_size = len(children)
        if children_size == 1:
            if nodes_connected(edges, children[0][0]) >= 4:
                return u
            return None
        if children_size == 0 or children_size >= 2:
            return u
        return None

    def nodes_connected(edges, node):
        frontier = [node]
        parent = [None] * len(edges) + [True]
        visited = [False] * len(edges) + [True]
        while frontier:
            node = frontier.pop()
            visited[node] = True
            for nxt in graph[node]:
                if not visited[nxt] and nxt != parent[node]:
                    frontier.append(nxt)
                    parent[nxt] = node
        if any((elem, parent[elem]) for elem in parent):
            return False
        return True

    u = dfs(node, None)
    if u in visited:
        return -1
    return u and (-1 if nodes_connected(edges, u) >= 4 else 1)

# Example usage
if __name__ == "__main__":
    N = int(input().strip())
    edges = [tuple(map(int, input().split())) for _ in range(N - 1)]
    print(is_good_cutting_point(edges, 0))
