def dijkstra(graph, start, n):
    time = [float('inf')] * (n+1)
    time[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_time, node = heappop(priority_queue)

        if current_time > time[node]:
            continue

        for neighbor in graph[node]:
            if current_time + graph[node][neighbor] + graph[node][node] - graph[neighbor][node] + time[node] <= graph[neighbor][neighbor]:
                new_time = current_time + graph[node][neighbor]
