from functools import lru_cache

def can_xor(array):
    @lru_cache(maxsize=None)
    def find_mask(n, k):
        if n < 2 ** k:
            return ((array[n] ^ array[n // 2]) >> (n % 2) & (1 << k - n % 2)) != 0
        return False

    mask_left = find_mask(0, k)
    return not any([mask_left, mask_left ^ 1] == find_mask(i, k) for i in range(1 << k))

def find_permutation(array):
    @lru_cache(maxsize=None)
    def decode(mask, nums, i, lookup):
        if i < 2 ** k:
            return list(zip(characters[i * 2 : (i + 1) * 2], lookup[i]))
        tm = lookup[i] ^ (mask >> i)
        return decode(tm, nums, nums.index(tm), lookup)

    @lru_cache(maxsize=None)
    def iterate_over_levels(mask, n_chars):
        if n_chars == 0:
            return []
        if mask == 0 or n_chars == 1:
            return [(mask, [])]
        results = []
        char, chars = decode(mask, n_chars, 0, lookup)
        for r in iterate_over_levels(mask & (mask >> 1), chars, n_chars - 1):
            for c in char:
                results.extend((mask & 1 << (2 * c - 1), (r[0] | r[1][c], r[1][c])))  # consider each true index
        return results

    characters = [i for i in range(pow(2, k))]
    indices = []
    lookup_masks = []
    size = 1 << k
    for level in range(k):
        mask = indices ^ lookup_masks
        res = iterate_over_levels(mask, size, k - level - 1)
        for m, f in res:
            if find_mask(0, k):
                indices += f
            res = iterate_over_levels((m & m >> 1) // 2, (m & m >> 1) % size, k - level - 1)
            for m, f in res:
                if find_mask(1 << (k - level - 1), k):
                    indices += f
                res = iterate_over_levels(m, (m % size) // (size // 2), k - level - 1)
                for m, f in res:
                    if find_mask(1 << (k - level - 2), k):
                        indices += f
        lookup_mask = decode(0, size, 0, lookup_masks)
        if lookup_mask[0][0] is lookup[0][1]:
            lookup_masks += lookup_mask[1:]
        else:
            lookup_masks += lookup_mask
        lookup_masks += [lookup_mask[-1][1]]

    position = -len(lookup_masks)
    return indices[:len(indices) - len(lookup_masks) - position], indices[len(indices) - len(lookup_masks) :]

