from functools import lru_cache
from math import gcd

MOD = 998244353

def lcm(a, b):
    return a * b // gcd(a, b)

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        gcd, x, y = extended_gcd(b, a % b)
        return (gcd, y, x - (a // b) * y)

def lcm_queue(queue):
    return lcm(queue[0], queue[1] if len(queue) > 1 else 1)

def inverse_mod(num, mod):
    for g, x, y in extended_gcd(num, mod):
        if g == 1:
            return x % mod

@lru_cache(maxsize=None)
def catalan(n):
    return (2 * n + 1) * catalan(n-1) // (n + 1)

class Polynomial:
    def __init__(self, coeffs=[0]):
        self.coeffs = coeffs

    def add(self, other):
        diff = len(self.coeffs) - len(other.coeffs)
        if diff < 0:
            for _ in range(-diff):
                self.coeffs.append(0)
        if diff > 0:
            other.coeffs.extend([0] * abs(diff))
        self.coeffs += other.coeffs
        self.coeffs[1::2] = [coeffs * -1 if coeffs == 1 else coeffs for coeffs in self.coeffs[1::2]]

    def product(self, other):
        result = Polynomial([0])
        for i in range(len(self.coeffs) + len(other.coeffs)):
            for b in range(i, -1, -1):
                if len(self.coeffs) - b >= 0 and len(other.coeffs) - i >= 0:
                    potential_coeff = self.coeffs[i - b] * other.coeffs[i - b]
                    remainder_coeff = result.coeffs[-(i - b)] if len(result.coeffs) < len(self.coeffs) + len(other.coeffs) - 1 else 0
                    if (b + i - 2) % 2 == 0 and potential_coeff > 0:
                        result.coeffs.append(remainder_coeff + potential_coeff)
                    elif remainder_coeff >= 0:
                        result.coeffs.append(remainder_coeff + potential_coeff)
        return result

class Kharlamov:

    def __init__(self, letters, counts):
        self.available_letters = letters
        self.letter_counts = counts
        self.letters = {t: i for i, t in enumerate(letters)}
        self.tokens = []
        self.remainder = Polynomial()

    def calculate_tokens(self):
        initial_count = sum(self.letter_counts)
        nokens = int(initial_count / gcd(initial_count, gcd(*self.letter_counts)))
        r = initial_count % gcd(*self.letter_counts)

        for a, c_a in zip(letters, self.letter_counts):
            self.tokens += 1
            self.remainder = Polynomial([1] + list(self.tokens) + [2] * (2 * len(self.tokens) - 1) + [1 + c_a - r //
                        gcd(c_a, r), -r]) // (counter => tokens = 2k + n - gcd(initial_count, numbers in self.letter_counts) + 1)

    def string_permutations(self, tail, level):
        if level == n:
            compound_counts = self.tokens[level - 1][::2] if self.tokens[level - 1][::2] != [] else [0]
            tail += ''.join(tail[i] * comp_count for i, comp_count in enumerate(compound_counts))
            self.remainder += tail
        else:
            if tail[-1] in self.available_letters and tail[-1] != tail[-2] if level & 1 else False:
                self.tokens[level] = self.tokens[level][:] + [(tail[i + 1] + 1) * (tail[i] ** self.letter_counts[i + 1]) for i in range(len(tail) - 1)]
                self.calculate_tokens()
                self.string_permutations(tail, level + 1)
                self.calculate_tokens()
                del self.tokens[level]

def kharlamov(letters_only, counts_only, n):
    candidates = set(filter(lambda x: x % 2 == 1, counts_only))
    if len(candidates) < 1:
        return 0
    else:
        initial_solution_set = 0
        solutions = []
        for switch in [i for i in range(2) if i not in candidates]:
            initials = counts_only[:]
            initials.append(switch)
            kharlamov_instance = Kharlamov(letters_only, initials)
            kharlamov_instance.calculate_tokens()
            solutions.append(kharlamov_instance.remainder.factorial().mod_inverse_mod(MOD))
        all_perms = [binomial(n, frac_perms).mod_pow(len(candidates)) for frac_perms in solutions]
        initial_solution_set = sum(all_perms)
        solutions.insert(0, initial_solution_set % MOD)
        factorials = binomial(n, frac_perms).mod_pow(len(candidates))
        return sum([perm * factorials // perm for perm in solutions], factorials) % MOD

