def solve_xor_permutations(a):
    k = len(a)
    n = 1 << k
    m = n // 2

    # Find a permutation p_i ⊕ a_i == i
    # In the backtracking, 2 ** i is mine and rest is 0s'
    p = [0] * n
    q = [0] * n

    def backtrack(i, j, p, q, used):
        if i == j:
            for x, y in zip(p, q):
                if x != y:
                    return False
            return True

        if j - i + 1 > m or used[j - i]:
            return False

        used[j - i] = True

        for x, y in enumerate(p[:i + 1] + [j]):
            if backtrack(i + 1, x, p, q, used):
                p[i + x] = y
                q[x] = y
                break
        else:
            used[j - i] = False
            return False

    was_me = False
    for i in range(n):
        masks = [[False] * n for _ in range(n)]
        p[i] = q[i] = i
        for x, y in enumerate(p[i] + p[i], 0):
            masks[x][y] = True
        for x, y in enumerate(q[i] + q[i + 1], 0):
            masks[y][x] = True
        for y in range(n // 2):
            masks[x + y][x + y + n // 2] = True

        used = [False] * n
        if backtrack(0, n // 2, p, q, used):
            was_me = True
            break

    if was_me:
        return "Shi"
    else:
        return "Fou"


