import heapq

def shortest_path(panels, target_indices, flips):
    heap = [(0, 0)]  # (cost, step)
    visited = {0: 0}
    steps = {}

    while heap:
        current_cost, current_step = heapq.heappop(heap)

        for next_step, index in enumerate(panels):
            if index in visited:
                continue

            if steps.get(index, float('inf')) < next_step:
                continue

            for ref_flip in range(1, flips[index] + 1):
                for move in range(index - ref_flip, index + ref_flip + 1):
                    steps[index] = min(steps.get(index, float('inf')), current_cost + abs(move - target_indices[current_step % len(target_indices)]))
